'use strict';
const {course}=require('./data-helper');
const specs=[
{id:'ma-dot',comps:['m1.c1','m1.c2'],practice_comps:['m1.c1','m1.c2','m1.c1','m1.c2','m1.c1','m1.c2','m1.c1'],formal_comps:['m1.c1','m1.c1','m1.c1','m1.c2','m1.c2','m1.c2','m1.c1','m1.c1','m1.c2','m1.c1'],title:'Represent a record as a vector and compute a dot product',intro:'A delivery model receives distance, package mass and service indicators. A vector is an ordered list of numerical coordinates, not an unordered bag of measurements. A dot product combines matching coordinates and makes the meaning of feature order and units concrete.',sections:[
['Coordinates carry a contract','Write x=(x1,…,xd) and a compatible weight vector w. Their dot product is Σ xi wi: multiply matching coordinates and add. The result is a scalar. For x=(2,3) and w=(4,−1), the product is 8−3=5. Negative weights can reduce a prediction; a negative coordinate is meaningful only under the feature’s definition.','Keep feature names, order, units and preprocessing alongside a model. Reversing two columns can silently produce a numerically valid but semantically wrong result. A distance in kilometres cannot be substituted with metres without changing the corresponding coefficient.'],
['Linear score versus business outcome','A score w·x+b is an affine function because the intercept b permits a nonzero output at x=0. It may be a price estimate, a decision score or an input to another function. A score alone is not a calibrated probability or proof of causation.','The worked example uses a deliberately small declared coefficient contract. The list representation is educational; production pipelines should validate schema and use tested numerical operations while preserving feature lineage.']
],problem:'Compute a two-feature synthetic delivery score with a fixed feature order.',steps:['Pair each feature with its declared coefficient.','Multiply each pair and sum.','Add the separately declared intercept.'],code:'x = [2, 3]\nw = [4, -1]\nassert len(x) == len(w)\nprint(sum(a*b for a,b in zip(x,w)))\nprint(sum(a*b for a,b in zip(x,w)) + 6)',expect:'5\n11',limit:'The output checks the arithmetic and intercept only. It does not validate the coefficient estimates, feature units or business fairness.',mistakes:['Truncating mismatched lists with zip hides missing features; validate lengths.','Changing feature order without coefficients changes the model meaning.'],takeaways:['A dot product contracts equal-length vectors to one scalar.','Feature contracts are part of numerical correctness.'],practice:[
['For vectors [2,3] and [4,-1], what is the dot product?','5','11','8','-5','Multiply matching coordinates: 2×4+3×(-1)=5; the intercept is separate.'],
['What must match before a dot product is defined?','Coordinate counts','Coordinate signs','Coordinate values','Vector magnitudes','The operands need the same dimension; equal values, signs or lengths in magnitude are unnecessary.'],
['Which model expression includes an intercept?','w·x+b','w·x only','x reordered','w without x','The additive constant shifts the score even when every input coordinate is zero.'],
['A parcel feature changes from kilograms to grams. What needs coordinated review?','Feature/weight units','Only the output font','Only the row identifier','Only the row count','Scaling a coordinate changes its numerical contribution unless the associated coefficient/preprocessing contract changes.'],
['A scoring function zips vectors of lengths three and two. What is the main concern?','Silent omitted coordinate','Guaranteed negative score','Automatic unit conversion','Guaranteed exception','Python zip truncates to the shorter iterable, so explicit shape validation prevents a silent incomplete score.'],
['A valid scalar score is returned after columns are swapped. What has not been established?','Semantic feature correctness','That addition occurred','That multiplication occurred','That the result is scalar','Compatible arithmetic shapes do not prove that weights were paired with their intended features.'],
['A score of 2.4 is labeled a probability. What additional design is needed?','Probability semantics','A larger intercept alone','A different list order','Integer-only coefficients','An unrestricted linear score is not bounded to [0,1] and needs an appropriate probabilistic model/calibration.']
],formal:[
['Which operation maps two compatible vectors to a scalar?','Dot product','Concatenation','Element deletion','Matrix transpose','A dot product sums paired-coordinate products; the other operations do not perform that contraction.'],
['For x=(1,2,3), w=(2,0,-1), what is w·x?','-1','1','5','-3','The paired products are 2,0,-3 and sum to -1.'],
['What distinguishes an affine score from a strictly linear transformation?','A possible nonzero intercept','Every coefficient is positive','Every input is categorical','The output must be a probability','A linear map sends zero to zero; an affine map may add a nonzero constant.'],
['A clinic reorders age and dosage columns while retaining old weights. What is the primary failure?','A broken feature contract','An invalid sum operator','A missing output vector','A guaranteed overflow','Weight positions carry feature meaning; valid arithmetic cannot repair a schema-order mismatch.'],
['A retail model multiplies price-in-cents by a coefficient fitted on dollars. What is needed?','Consistent unit conversion','A new customer identifier','A different matrix label','A larger sample counter','The scale of input values and corresponding coefficients must agree with training and interpretation.'],
['A risk score uses five input fields but one weight is absent. What should serving do?','Reject the shape mismatch','Truncate the fifth input','Guess a random coefficient','Repeat the last coefficient','A missing coefficient violates the declared feature dimension; an explicit schema error is safer than an invented model.'],
['A support dashboard interprets a positive coefficient as causal impact. What is missing?','Causal identification','A larger dot-product value','A nonzero customer count','A positive output intercept','Fitted predictive association alone does not identify the effect of intervening on a feature.'],
['A logistics score adds an intercept twice, once in preprocessing and once in serving. What changes?','The prediction baseline','The feature vector length','The multiplication definition','The coordinate names','Repeated addition of the intercept shifts every prediction without changing the feature contributions.'],
['A school score is correct only for one row because feature names are discarded upstream. Which test is most useful?','Schema/order invariant tests','Only a scalar type check','Only a positive-score check','Only a screenshot of output','Invariants that bind names, order and units target the semantic error; type/sign/presentation do not.'],
['Two teams rescale x by a nonzero factor k. Which coefficient change preserves w·x for all x?','Divide w by k','Multiply w by k','Add k to every weight','Leave all weights fixed','The paired factors cancel: (w/k)·(kx)=w·x; adding or multiplying weights does not generally preserve the score.']
]},
{id:'ma-norm',comps:['m1.c1','m1.c2'],practice_comps:['m1.c2','m1.c1','m1.c2','m1.c2','m1.c2','m1.c1','m1.c2'],formal_comps:['m1.c1','m1.c2','m1.c1','m1.c2','m1.c2','m1.c1','m1.c1','m1.c2','m1.c1','m1.c2'],title:'Read matrix shapes and measure vector magnitude',intro:'An analytics table contains samples as rows and features as columns. Shape tells us how a mathematical operation uses that table. Magnitude describes a vector’s size under a chosen norm; neither shape nor size says whether its feature meaning is appropriate.',sections:[
['Rows, columns and compatible multiplication','If X has n samples and d features, its shape is n×d. Multiplying X by a d×1 weight column yields n×1 predictions. In a general product A(m×k)B(k×p), the inner dimensions k agree and the result is m×p. A transpose exchanges axes; it does not invent missing observations.','A batch with one sample may be represented as 1×d or as a length-d vector under library conventions. State the convention instead of assuming broadcasting has the intended semantics. A library accepting an operation is not proof that sample and feature axes are aligned.'],
['Magnitude and the choice of geometry','The Euclidean or L2 norm is sqrt(Σ xi²); the L1 norm is Σ|xi|. For (3,4), these are 5 and 7. Norms are nonnegative and zero only for the zero vector. Normalizing by the L2 norm yields unit magnitude when the vector is nonzero.','Distances and angles depend on scaling and representation. A large-magnitude salary feature can dominate an unscaled distance compared with an indicator. Fit preprocessing on training data, keep the transformation with serving and handle zero vectors explicitly.']
],problem:'Inspect two rows, calculate their scores and compare two norms of one row.',steps:['Record row and feature counts.','Apply one compatible weight vector to both rows.','Compute L2 and L1 separately rather than interchanging their meanings.'],code:'import math\nX = [[3,4], [0,2]]\nw = [2,1]\nassert all(len(row)==len(w) for row in X)\nprint((len(X), len(w)))\nprint([sum(a*b for a,b in zip(row,w)) for row in X])\nprint(math.sqrt(sum(v*v for v in X[0])))\nprint(sum(abs(v) for v in X[0]))',expect:'(2, 2)\n[10, 2]\n5.0\n7',limit:'This tiny list implementation verifies declared dimensions and arithmetic, not floating-point stability or large-batch performance.',mistakes:['Confusing sample count with feature count makes compatible-looking arrays mean the wrong thing.','Dividing a zero vector by its norm is undefined.'],takeaways:['Inner dimensions determine multiplication compatibility.','A norm is a declared measure, not a universal notion of relevance.'],practice:[
['A table has 20 samples and 4 features. Under samples-as-rows, what is its shape?','20×4','4×20','20×20','4×4','Samples define rows and features define columns under the stated convention.'],
['What is the L2 norm of (3,4)?','5','7','12','25','The square root of 3²+4² is 5; 7 is L1 and 25 is squared L2.'],
['What output shape follows (8×3)(3×2)?','8×2','3×3','8×3','2×8','The common inner axis is contracted, leaving the first operand’s rows and second operand’s columns.'],
['A single observation has length d. What must be checked before batching it?','The explicit axis convention','Only that d is positive','Only the dataset filename','Only the response format','A 1×d row and d×1 column have different roles; library conventions must match the intended sample axis.'],
['A nearest-neighbor model uses salary and a binary flag without scaling. What may happen?','Large units dominate distance','All distances become zero','Shapes always become invalid','Every neighbor becomes causal','Distance weights numerical scale; a large-unit feature can overwhelm a smaller-scale signal.'],
['An embedding is all zeros. What must normalization handle?','Its zero denominator','An extra sample axis','A mandatory negative norm','A guaranteed cosine of one','The zero vector has norm zero, so division requires an explicit zero-vector policy.'],
['An array operation broadcasts without error. What still needs validation?','Intended axis semantics','That syntax was parsed','That memory exists','That a result was returned','Broadcasting can be computationally valid while pairing the wrong sample/feature axes.']
],formal:[
['What is the L1 norm of (-2,5)?','7','3','-7','29','L1 sums absolute coordinates: 2+5=7.'],
['Which shapes permit an ordinary matrix product?','(4×3) and (3×2)','(4×3) and (4×2)','(4×3) and (2×3)','(4×3) and (4×3)','The first matrix’s column count must equal the second matrix’s row count.'],
['Which vector cannot be divided by its L2 norm to form a unit vector?','The zero vector','A negative coordinate vector','A length-two vector','A vector with norm two','Only zero norm makes the normalization denominator zero; negative coordinates are allowed.'],
['A retailer stores 100 baskets with 6 features. What is the conventional prediction shape for one scalar per basket?','100×1','6×1','1×6','6×100','A 100×6 feature matrix multiplied by a 6×1 coefficient column produces 100 scalar predictions.'],
['An image model expects channels-last but receives channels-first. What should be verified?','Axis meaning and layout','Only total element count','Only the tensor filename','Only whether values are numeric','Equal total size does not establish the correct spatial/channel semantics.'],
['A fraud model normalizes (0,0). What is an appropriate implementation requirement?','Explicit zero-vector handling','Automatic division by zero','A random unit direction','Silently infinite coordinates','A documented fallback or rejection avoids an undefined operation and invented feature meaning.'],
['A report labels sqrt(sum(x²)) as squared distance. What is wrong?','Rooted versus squared','Negative inputs are forbidden','Every norm is integer-valued','A norm must keep direction','The square root produces Euclidean magnitude; squared magnitude omits that root.'],
['A team transposes an n×d table to fix an error but keeps the old interpretation. What is at risk?','Sample/feature role reversal','Guaranteed duplicate values','Loss of every coefficient','Mandatory negative dimensions','Transposition exchanges axes; downstream contracts must reflect that exchange.'],
['A hospital uses two numerical features in different units for geometric similarity. Which choice is defensible?','Justify scaling from the task','Treat all raw units as equal','Fit scaling on held-out labels','Normalize each label as a feature','Scaling choices need a task rationale and training-only fit to avoid dominance and leakage.'],
['A pipeline passes shape tests but swaps two feature names. Which conclusion is accurate?','Shape is insufficient','Equal shapes prove correctness','Transpose always repairs meaning','Unit norm restores feature identity','Dimension compatibility does not certify that coordinates represent the intended measurements.']
]},
{id:'ma-matrix',comps:['m1.c1','m1.c2'],practice_comps:['m1.c2','m1.c1','m1.c1','m1.c1','m1.c2','m1.c1','m1.c2'],formal_comps:['m1.c1','m1.c1','m1.c2','m1.c1','m1.c1','m1.c2','m1.c2','m1.c1','m1.c1','m1.c1'],title:'Compose matrix products without losing semantic dimensions',intro:'A recommendation service maps three customer features to two intermediate scores, then to one ranking score. Matrix multiplication can combine these stages, but the order of the transformations matters.',sections:[
['A product applies one linear combination after another','Each output coordinate of Ax is a dot product between one row of A and x. For two compatible linear maps, B(Ax)=(BA)x. This associativity allows composition without changing the mathematical result in exact arithmetic. Floating-point roundoff may differ because sums are grouped differently.','Matrix multiplication generally is not commutative: BA and AB may have different shapes, or both may exist and differ. Identity I leaves vectors unchanged when dimensions match. A diagonal matrix scales coordinates independently, while a general matrix can mix them.'],
['Check the units of intermediate representations','Name the intermediate axes: features, latent factors, locations or outcomes. A shape 2×2 does not guarantee that two matrices use the same coordinate basis. Addition/subtraction also requires matching axes and units.','The example composes a two-dimensional scale with a mixing transform and shows that exchanging order changes the result. Its small integer arithmetic is exact; this does not establish numerical conditioning of a learned system.']
],problem:'Apply scaling and mixing in both orders to observe noncommutativity.',steps:['Define one vector and two explicit two-by-two maps.','Apply scaling before mixing.','Reverse the order and compare outputs.'],code:'def mv(A,x):\n    assert all(len(r)==len(x) for r in A)\n    return [sum(a*b for a,b in zip(r,x)) for r in A]\nscale = [[2,0],[0,1]]\nmix = [[1,1],[0,1]]\nx = [1,2]\nprint(mv(mix,mv(scale,x)))\nprint(mv(scale,mv(mix,x)))',expect:'[4, 2]\n[6, 2]',limit:'The different outputs establish the chosen maps do not commute. General numerical stability and learned model suitability need separate analysis.',mistakes:['Reordering a product for convenience can change the transformation.','Equal matrix sizes do not guarantee equal coordinate meanings.'],takeaways:['A matrix row defines an output linear combination.','Composition order is a semantic and algebraic contract.'],practice:[
['What does one row of A contribute to Ax?','One output dot product','One input deletion','One new sample id','One sorted coordinate','Each matrix row combines the input coordinates into a corresponding output scalar.'],
['Which identity is generally valid for compatible exact matrix arithmetic?','B(Ax)=(BA)x','AB=BA always','A+B=AB always','Ax=x for every A','Associativity allows composition; commutativity and identity behavior require special matrices.'],
['A diagonal map has entries 2 and 1. What does it do to (1,2)?','Produces (2,2)','Produces (3,3)','Produces (1,4)','Produces (2,1)','Diagonal multiplication scales the matching coordinate independently.'],
['Two compatible stages are reversed in serving. What should a reviewer expect?','Possibly different outputs','Guaranteed identical scores','Automatic matrix inversion','Only changed comments','General matrix transformations do not commute, even when dimensions happen to permit both orders.'],
['A feature-space matrix is added to a same-shaped location-space matrix. What is missing?','Compatible axis meanings','Only a shared row count','Only numerical values','Only an addition function','Matching dimensions alone cannot justify adding different semantic coordinates.'],
['A team combines two fitted linear maps into one product. What should still be tested?','Equivalence within precision policy','That every matrix is square','That all weights are positive','That both matrices are diagonal','Associative algebra supports composition, but finite precision and representation contracts need verification.'],
['A ranking transform uses rows as outputs. Which shape maps d inputs to k outputs?','k×d','d×k always','d×d only','k×k only','Each of k output rows requires d input coefficients.']
],formal:[
['Which matrix leaves compatible vectors unchanged?','Identity','Zero','Any diagonal matrix','Any square matrix','An identity matrix has diagonal ones and off-diagonal zeros, preserving each coordinate.'],
['What is generally false about matrix multiplication?','It is always commutative','It can compose linear maps','It needs compatible axes','It uses sums of products','AB and BA can differ or one can be undefined, so unrestricted commutativity is false.'],
['A map has 5 outputs and 3 input coordinates. What is its row-by-column shape?','5×3','3×5','5×5','3×3','Each output row contains one coefficient for each of the three inputs.'],
['A logistics pipeline first converts units then mixes features. Why record the order?','The maps may not commute','The units remove all shape rules','Any order preserves the score','Mixing always cancels conversion','Coordinate scaling followed by mixing generally differs from mixing followed by scaling.'],
['A team replaces B(Ax) by (BA)x. Which property supports this?','Associativity','Universal commutativity','Independent coordinates','Mandatory invertibility','Associativity holds for compatible exact products; no inverse or arbitrary reordering is required.'],
['A deployed matrix has the right size but a different feature basis. What follows?','Numerical compatibility is insufficient','All predictions are guaranteed equal','Identity labels repair all values','Only storage space is affected','Coefficients depend on the chosen basis and feature representation, not dimensions alone.'],
['A financial team adds two prediction vectors from different currencies. What is required?','A consistent unit contract','Only matching record count','A larger coefficient matrix','Only decimal formatting','Adding semantically comparable outputs requires aligned units as well as aligned observations.'],
['A batch product is parallelized and differs in the last decimal place. What is an appropriate first check?','Floating-point tolerance policy','Assume malicious data changes','Require exact decimal equality','Discard all multiplication tests','Different summation order can change roundoff; expected precision should be specified and tested.'],
['A model uses a zero matrix before a second linear layer. With no intercepts, what remains?','The zero output','The original feature vector','A guaranteed unit vector','A random preserved direction','The first zero map removes every input contribution; a later linear map sends zero to zero.'],
['Two square maps commute on one observed vector. What can be concluded?','Only that tested input agrees','The maps commute universally','The matrices must be identical','Every future score is equal','Agreement on one vector does not establish equality of transformations on the whole vector space.']
]},
{id:'ma-transform',comps:['m2.c1'],title:'Recognize linear transformations and changes of basis',intro:'A mapping can scale, rotate or mix feature vectors while preserving linear structure. Recognizing that structure clarifies what a model can represent and what an offset changes.',sections:[['Linearity is a testable algebraic property','A map T is linear when T(ax+by)=aT(x)+bT(y) for every compatible x,y and scalars a,b. Consequently T(0)=0. Matrix multiplication represents such a map in chosen bases. Adding a nonzero fixed bias makes the map affine rather than linear.','Testing a few vectors can reveal a violation but cannot in general prove universal linearity of an arbitrary program. For a specified matrix map, the algebraic definition provides the proof. Nonlinear operations such as squaring, clipping and maximum can break superposition.'],['Representations and geometric intuition','Rotation preserves Euclidean lengths when its matrix is orthogonal; a projection may discard a direction. A transformation can be linear without being invertible. If information is discarded, no inverse can recover every original input.','A change of basis describes the same vector using different coordinates, while applying a map may change the vector itself. Keep the basis convention explicit when interpreting model coefficients or comparing embeddings.']],problem:'Check a linear mixing map against a nonzero-bias map using zero and addition.',steps:['Evaluate both maps at zero.','Compare T(x+y) with T(x)+T(y).','Identify which condition fails for the offset map.'],code:'def T(x): return [2*x[0]+x[1], x[1]]\ndef F(x): return [2*x[0]+x[1]+3, x[1]]\nx,y=[1,2],[2,1]\nadd=lambda a,b:[u+v for u,v in zip(a,b)]\nprint(T([0,0]))\nprint(T(add(x,y)) == add(T(x),T(y)))\nprint(F([0,0]))',expect:'[0, 0]\nTrue\n[3, 0]',limit:'These checks illustrate the algebra for explicitly defined maps. A finite test set alone would not prove arbitrary code linear for every possible input.',mistakes:['A nonzero intercept is affine even when every other operation is a dot product.','Linearity does not imply invertibility or preserved distances.'],takeaways:['Superposition defines linearity.','State the basis and distinguish a map from a coordinate change.'],practice:[
['What must every linear map do to the zero vector?','Return zero','Return one','Return its bias','Return an eigenvalue','Homogeneity gives T(0)=0 for a linear map.'],
['Which map is affine but not linear when b is nonzero?','Ax+b','Ax','0x','Ix','The nonzero constant breaks zero preservation and superposition.'],
['Which operation generally breaks linearity?','Squaring each coordinate','Multiplying by a fixed matrix','Adding compatible linear maps','Scaling by a fixed scalar','Squaring does not preserve arbitrary sums or scalar multiplication.'],
['A projection discards a coordinate. What property may be lost?','Invertibility','Linearity necessarily','Every shape convention','All deterministic behavior','Different inputs can share the same projection, so a unique inverse need not exist.'],
['A feature transform preserves superposition but changes lengths. What is possible?','Linear, nonorthogonal','It cannot be a matrix map','It must contain a bias','It must be nonlinear','Linearity concerns sums/scalars; orthogonality supplies Euclidean length preservation.'],
['A team checks T(x+y)=T(x)+T(y) on one pair. What is justified?','Agreement on that pair','A universal program proof','Guaranteed invertibility','Guaranteed unit norm','A finite example is evidence for that input, not a general proof about an arbitrary implementation.'],
['Two embeddings use different bases. Before comparing coordinates, what is required?','A representation alignment','Only equal vector lengths','Only matching file formats','Only positive coordinates','Coordinates have meaning relative to a basis; equal dimensions do not align different representations.']
],formal:[
['Which condition is part of linearity?','T(ax)=aT(x)','T(0)=1','T(x)=x always','T(x) is always positive','Homogeneity and additivity together define a linear transformation.'],
['Can a linear transformation be noninvertible?','Yes, a projection can be','No, linear means bijective','Only with a nonzero bias','Only with random input','A map that discards a direction is linear but not one-to-one.'],
['What does an orthogonal transformation preserve?','Euclidean norm','Every coordinate value','Every feature name','The sign of each coordinate','An orthogonal matrix satisfies QᵀQ=I and preserves the Euclidean inner product.'],
['A sensor service adds a fixed calibration offset. How should the resulting map be classified?','Affine in general','Strictly linear always','Necessarily invertible','Necessarily orthogonal','A fixed nonzero offset changes the image of zero and thus breaks strict linearity.'],
['A recommender clips negative scores to zero. What needs recognition?','A nonlinear stage','An identity transformation','Guaranteed rotation','An invertible projection','Clipping fails general superposition and is not represented by one fixed linear map.'],
['A dashboard drops one feature before scoring. Why might reconstruction fail?','Information was discarded','Every matrix was transposed','Lengths must be preserved','The output became random','Many input vectors can map to the same reduced representation.'],
['A team rotates all two-dimensional features with an orthogonal matrix. What remains equal?','Their Euclidean lengths','Every original coordinate','Each coordinate sign','Every axis interpretation','A rotation preserves geometric lengths while changing coordinate values.'],
['A matrix implementation is proven distributive algebraically. What do unit tests add?','Checks of actual implementation','A replacement for all assumptions','Universal proof of business fit','Evidence of causal fairness','Tests can catch coding/shape mistakes in a stated mathematical model, not prove all business claims.'],
['A customer model compares coefficients across two different feature bases. What must be reviewed?','The coordinate transformation','Only coefficient file sizes','Only the row sort order','Only display precision','Coefficients depend on the representation used for inputs; basis changes alter their coordinate form.'],
['An unknown program passes zero preservation. Does that prove linearity?','No, other laws still matter','Yes, zero is the only test','Yes, if output is numeric','Only if the input has two axes','For example x↦x² sends zero to zero but violates general additivity and homogeneity.']
]},
{id:'ma-eigen',comps:['m2.c1'],title:'Interpret eigenvectors and eigenvalues as stable directions',intro:'Some directions are only scaled by a transformation rather than redirected. These eigenvector directions help explain repeated transformations and the variance axes used by PCA.',sections:[['Define the direction before calculating the scale','For a square matrix A, a nonzero vector v is an eigenvector if Av=λv for some scalar λ. The scalar λ is its eigenvalue. The zero vector is excluded because it trivially satisfies the equation for every λ and supplies no direction. Scaling an eigenvector by a nonzero constant gives the same eigen-direction.','For a diagonal matrix with diagonal entries 3 and 1, the coordinate directions are eigenvectors with those scales. An eigenvalue can be zero or negative; zero means that direction is annihilated and a negative value reverses direction as well as scaling magnitude.'],['What eigen-analysis does and does not imply','Not every real square matrix has a full real eigenvector basis. Symmetric covariance matrices have real eigenvalues and an orthonormal basis, making them particularly useful for PCA. Near-equal eigenvalues can make individual axis directions unstable while the associated subspace remains useful.','An eigenvector of a covariance matrix identifies a direction in feature space, not a customer record or a causal explanation. Units, centering and sampling decisions still determine the covariance being analyzed.']],problem:'Verify two eigen-directions of an explicit diagonal transformation.',steps:['Apply the matrix to two nonzero coordinate directions.','Compare each result with a scalar multiple of its original vector.','Inspect the sign and magnitude of the scales.'],code:'A=[[3,0],[0,-1]]\ndef mv(x): return [sum(a*b for a,b in zip(r,x)) for r in A]\nprint(mv([2,0]))\nprint(mv([0,2]))\nprint(mv([1,1]))',expect:'[6, 0]\n[0, -2]\n[3, -1]',limit:'The first two vectors are eigenvectors with scales 3 and -1. The final vector is not proportional to its image; no general eigensolver or convergence claim is involved.',mistakes:['The zero vector is not a valid eigenvector direction.','A principal direction is not automatically a causal business driver.'],takeaways:['Eigenvectors preserve direction up to scalar sign.','Covariance symmetry provides useful PCA geometry.'],practice:[
['Which equation defines a nonzero eigenvector?','Av=λv','Av=v+λ always','A+v=λ','v=0','A matrix maps an eigenvector to a scalar multiple of itself.'],
['Why is the zero vector excluded?','It supplies no direction','It has a negative norm','It is always nonlinear','It cannot be multiplied','Zero would satisfy the relation trivially for every eigenvalue and cannot identify a direction.'],
['What does a negative eigenvalue do along its eigenvector?','Reverses and scales','Always rotates by ninety degrees','Always erases the vector','Makes its norm negative','The scalar sign reverses orientation while its absolute value scales magnitude.'],
['A sensor covariance has nearly equal leading eigenvalues. What should a report acknowledge?','Axis orientation may be unstable','The observations must be invalid','Every axis is causal','The variance must be negative','Similar eigenvalues can make individual estimated directions sensitive to perturbations.'],
['A retailer doubles an eigenvector without changing its direction. What happens to its eigenvalue?','It stays the same','It doubles necessarily','It becomes zero','It changes sign','Linearity gives A(cv)=cAv=λ(cv) for any nonzero c.'],
['A model has an eigenvalue zero. What occurs to that eigen-direction?','It maps to zero','It becomes unit length','It is amplified infinitely','It changes feature units','The relation Av=0v means the map annihilates that nonzero direction.'],
['A principal component is reported as a causal sales lever. What is missing?','A causal design/argument','A larger eigenvalue alone','A normalized axis alone','A square covariance matrix','Variance directions summarize association and cannot by themselves identify intervention effects.']
],formal:[
['For diag(4,2), which vector has eigenvalue four?','(1,0)','(0,1)','(1,1)','(0,0)','The first coordinate direction is multiplied by four; the zero vector is excluded.'],
['If Av=λv and c is nonzero, what is A(cv)?','λ(cv)','c+λ+v','Always zero','v/c','Linearity preserves the eigenvalue along every nonzero scalar multiple of the eigenvector.'],
['Which matrix class gives real orthogonal eigendirections for PCA covariance?','Real symmetric matrices','All rectangular matrices','All arbitrary square matrices','Only identity matrices','Real symmetric covariance matrices admit an orthonormal eigenbasis with real eigenvalues.'],
['A variance analysis finds one eigenvalue close to zero. What may it indicate?','Low directional variance','Causal irrelevance is proved','Every sample is duplicated','The feature count is zero','A small covariance eigenvalue describes low spread along its direction, not a universal causal conclusion.'],
['A service repeatedly applies a diagonal map with eigenvalue two to an eigenvector. What happens in exact arithmetic?','Magnitude doubles each application','Direction rotates each application','Magnitude halves each application','The vector becomes zero at once','Each multiplication scales that eigendirection by two, so repeated applications compound the scale.'],
['An analyst labels the longest customer row an eigenvector automatically. Why is that unsupported?','The defining equation was not checked','Every eigenvector has unit length','Rows cannot be numeric','A covariance matrix has no rows','Magnitude alone does not imply that the transformation maps the vector to a scalar multiple.'],
['A system has a negative eigenvalue with magnitude below one. What happens along that direction under repetition?','Alternating shrinking magnitude','Alternating growing magnitude','Constant positive coordinates','One-time permanent rotation','The negative sign alternates orientation while the absolute value below one contracts magnitude.'],
['A covariance estimate changes slightly and its top two eigenvectors rotate greatly. Which context matters?','The gap between eigenvalues','Only total file size','Only whether labels are strings','Only the matrix storage format','A small spectral gap can make individual estimated axes sensitive even if the shared subspace is stable.'],
['A report compares component coefficients before and after rescaling one feature. What must be acknowledged?','The covariance geometry changed','Eigenvectors ignore units','Only the intercept changed','All directions are invariant','Changing coordinate scale changes the covariance matrix and potentially its eigenvectors.'],
['A team wants every real matrix to have a real eigenbasis for dimensionality reduction. What is wrong?','That property is not universal','Every real matrix is symmetric','Rectangular maps are always invertible','All eigenvalues must be positive','A full real eigenbasis needs additional conditions; symmetric covariance matrices have the useful guarantee.']
]},
{id:'ma-pca',comps:['m2.c1'],title:'Connect centered covariance, PCA and lost information',intro:'PCA compresses numerical features by choosing directions of high variance. A two-sensor example shows why centering and scaling choices belong in the analysis contract, and why compression is not the same as supervised prediction.',sections:[['Center the reference data and interpret variance','Subtract each training feature mean before forming the usual covariance matrix. A sample covariance uses a divisor n−1; a population covariance uses n. State which quantity is being estimated. For two features, covariance measures how centered coordinates vary together; it does not identify a causal mechanism.','PCA orders orthogonal covariance eigenvectors by eigenvalue. Projecting onto the first k directions retains the greatest sample variance among k-dimensional orthogonal linear projections under that covariance objective. This is a variance criterion, not a guarantee of preserving labels, rare events or business utility.'],['Fit once and preserve the transformation','Fit means, scaling and component axes using training data only. Apply the saved transformation to validation/test/serving data. Fitting preprocessing on evaluation observations leaks information about the held-out distribution. Large-unit features can dominate covariance unless an appropriate standardization policy is chosen.','The worked example has perfectly co-varying centered points on a line, so a hand-chosen unit direction captures their variation exactly. General data requires a reliable decomposition method and validation of retained information; no eigensolver is claimed here.']],problem:'Project centered diagonal points onto their known unit direction and reconstruct them.',steps:['Center the two synthetic observations.','Use a unit vector on their common direction.','Project and reconstruct to inspect retained information.'],code:'import math\nX=[[1.,1.],[3.,3.]]\nmean=[sum(row[j] for row in X)/len(X) for j in range(2)]\nu=[1/math.sqrt(2),1/math.sqrt(2)]\ncentered=[[v-m for v,m in zip(row,mean)] for row in X]\nz=[sum(a*b for a,b in zip(row,u)) for row in centered]\nreconstructed=[[round(m+t*v,6) for m,v in zip(mean,u)] for t in z]\nprint(mean)\nprint([round(v,6) for v in z])\nprint(reconstructed)',expect:'[2.0, 2.0]\n[-1.414214, 1.414214]\n[[1.0, 1.0], [3.0, 3.0]]',limit:'Exact reconstruction occurs because these points lie on the chosen line. Arbitrary one-component projections generally lose orthogonal information and need a tested numerical decomposition.',mistakes:['Fitting centering or scaling using held-out data leaks evaluation information.','High variance is not equivalent to predictive relevance or fairness.'],takeaways:['PCA acts on a specified centered/scaled representation.','Validate the downstream cost of discarded directions.'],practice:[
['Why center features in ordinary covariance-based PCA?','Measure spread around means','Force every value positive','Make all features causal','Remove every unit difference','Centering removes the mean location so covariance describes variation around that location.'],
['What determines PCA component ordering?','Covariance eigenvalues','Row identifiers','Label alphabet','File timestamps','Eigenvalues quantify variance along the orthogonal covariance directions.'],
['Does high retained variance guarantee retained predictive signal?','No','Yes for every dataset','Only when labels are strings','Only when values are positive','PCA is unsupervised; a low-variance direction can still carry crucial label or rare-event information.'],
['A model fits PCA using training plus final-test data. What is compromised?','Held-out evaluation independence','The ability to multiply vectors','Every covariance symmetry rule','The number of output columns','Using test distribution information in fitted preprocessing contaminates the intended held-out evaluation.'],
['A one-component reconstruction misses an orthogonal deviation. What is this?','Projection information loss','A mandatory coding failure','Proof of perfect prediction','A negative sample count','A lower-dimensional projection generally discards components outside the retained subspace.'],
['Two measurements differ mainly because one uses large numerical units. What should be reviewed?','The scaling policy','Only component labels','Only sorting order','Only decimal printing','Covariance-based variance can be dominated by scale, so preprocessing must match the analysis objective.'],
['The example reconstructs every toy point exactly. What remains unsupported?','Universal lossless compression','The stated toy arithmetic','The use of a unit direction','That the mean was computed','Points on one line permit that special reconstruction; general data contains other directions.']
],formal:[
['What is the mean of observations (1,1) and (3,3)?','(2,2)','(1,3)','(4,4)','(0,0)','Feature-wise averaging gives two for each coordinate.'],
['What does one covariance eigenvalue measure in PCA?','Variance along its direction','Number of customer rows','A causal effect estimate','The feature’s original mean','The eigenvalue describes spread of centered observations along that component direction.'],
['Which quantity is usually subtracted before covariance PCA?','Training feature means','The final test label','Every row identifier','The largest eigenvalue','Conventional PCA centers feature coordinates using fitted training means.'],
['A banking model discards a rare-fraud direction because its variance is small. What must be checked?','Downstream detection utility','Only retained variance total','Only file compression ratio','Only component count','The variance objective does not guarantee preservation of rare but important predictive signals.'],
['A dashboard compares PCA models fitted with dollars versus cents. Why can results differ?','Coordinate scaling changes variance','Means no longer exist','Every matrix becomes nonsquare','PCA automatically detects units','Unit scaling changes covariance geometry unless preprocessing deliberately compensates.'],
['A service receives new data after training. Which transformation should it use?','Saved centering and axes','Refit on each request','Fit using future labels','Random fresh axes','Serving must preserve the fitted representation contract; uncontrolled refitting changes the model inputs.'],
['A two-dimensional cloud has variation off the first component. What does one-component reconstruction omit?','The orthogonal residual','The entire mean necessarily','Every retained score','Every original sample id','Projection retains the selected subspace and loses orthogonal deviations.'],
['A researcher says PCA discovers treatment effects because axes are orthogonal. What is missing?','Causal identification','A square data table','An extra normalization','A sorted feature list','Orthogonality is geometric; it does not control confounding or identify intervention effects.'],
['A team uses n rather than n−1 in covariance. What should the report clarify?','Population versus sample convention','That all values are integers','That PCA cannot be computed','That all directions are invalid','The denominator changes the variance scale; the statistical quantity and convention must be explicit.'],
['A linear projection preserves 99% variance but removes a protected-group signal needed for audit. What is required?','Task-specific loss assessment','Automatic production approval','Only the variance percentage','Removal of every audit metric','Variance retention is only one criterion and cannot substitute for evaluating business, fairness and safety consequences.']
]},
{id:'ma-derivative',comps:['m3.c1'],title:'Read a derivative as local sensitivity',intro:'A model’s loss measures prediction error. A derivative tells us how that loss changes for a small change in one parameter, providing a local direction rather than a complete business judgment.',sections:[['From differences to local rates','For a scalar function f, the derivative f′(x) is the limit of [f(x+h)−f(x)]/h as h approaches zero when the limit exists. Its sign indicates local increase or decrease and its units are output units per input unit. For f(x)=(x−3)², the derivative is 2(x−3).','A finite difference approximates a derivative using a nonzero step. Very large steps measure a broader interval rather than the local slope; very small steps can suffer floating-point cancellation. Central differences [f(x+h)−f(x−h)]/(2h) are useful checks for smooth functions, not a universal substitute for analytic derivatives.'],['Local information has limits','At a differentiable interior optimum, a derivative is zero, but zero derivative alone does not establish a minimum: a maximum or a flat inflection can also be stationary. Boundaries and nondifferentiable points require separate reasoning.','The example compares an analytic slope with a central-difference estimate for a quadratic. Real objectives can be noisy, constrained or nonsmooth; use gradient checks and an optimization method appropriate to those assumptions.']],problem:'Compare an analytic derivative with a central finite difference.',steps:['Define a smooth synthetic quadratic.','Evaluate its analytic derivative at zero.','Compare a finite difference and inspect a stationary point.'],code:'f=lambda x:(x-3)**2\nx,h=0.,0.001\nprint(2*(x-3))\nprint(round((f(x+h)-f(x-h))/(2*h),6))\nprint(2*(3-3))',expect:'-6.0\n-6.0\n0',limit:'The agreement checks this smooth quadratic at chosen values. It does not establish accuracy for all step sizes or prove global optimality for arbitrary losses.',mistakes:['A zero derivative can be a maximum or saddle rather than a minimum.','An arbitrarily tiny finite-difference step can worsen roundoff.'],takeaways:['Derivatives quantify local sensitivity.','Check analytic reasoning and numerical assumptions together.'],practice:[
['What is the derivative of (x−3)²?','2(x−3)','x−3','2x+3','(x−3)²','The power and chain rules give twice the inner expression times its derivative one.'],
['A negative derivative means what locally?','Increasing x decreases f','Increasing x always increases f','f must be negative','x is globally optimal','The derivative sign describes local rate, not the function’s absolute value or a global conclusion.'],
['Does a zero derivative alone prove a minimum?','No','Yes for every function','Only if x is positive','Only for integer outputs','Stationary maxima and inflections also have zero derivative; additional reasoning is necessary.'],
['A gradient check uses an extremely small finite-difference step. What can hurt accuracy?','Cancellation and roundoff','A guaranteed exact answer','Automatic unit removal','A missing row count','Subtracting nearly equal floating-point values can amplify roundoff when divided by a tiny step.'],
['A price curve has a kink at a policy boundary. What assumption needs review?','Differentiability there','Whether its values exist','Whether prices have units','Whether subtraction is legal','One-sided slopes may differ at a kink; an ordinary derivative may not exist.'],
['A derivative has units cost per kilogram. What does it represent?','Local marginal cost','Total shipment cost','An input mass alone','A unit-free probability','The derivative carries output units divided by input units and describes marginal sensitivity.'],
['A test confirms one finite difference matches one formula. What is justified?','Local check at that point','Proof for every objective','Proof of a unique minimum','Proof of causal relevance','A numerical check can expose errors but finite sampling does not prove all-function claims.']
],formal:[
['What does f′(x) describe?','A local rate of change','A row identifier','A global maximum always','The mean of all x','A derivative is the limiting change in output per small input change.'],
['For f(x)=x², what is f′(2)?','4','2','8','0','The derivative 2x evaluated at two equals four.'],
['Which method uses values on both sides of x?','Central difference','Sorting observations','Counting records','Normalizing labels','A central difference uses f(x+h) and f(x−h) to approximate the local derivative.'],
['An engineer lowers a parameter when its loss derivative is positive. What is the local rationale?','Move against increasing loss','Always maximize the loss','Force every weight negative','Guarantee a global optimum','A small step opposite the positive derivative can reduce a smooth local objective.'],
['A stock-cost model is minimized at a feasible boundary where slope is nonzero. Is that possible?','Yes, constraints matter','No, every optimum has zero slope','Only for random functions','Only if the cost is negative','The zero-derivative condition applies to differentiable interior extrema, not every constrained boundary.'],
['A central-difference check uses h so large it crosses multiple regimes. What is at risk?','A poor local approximation','Automatic exact differentiation','Guaranteed convergence','A lost matrix dimension','A large interval may fail to approximate the derivative at the intended point.'],
['A loss has derivative zero at a strict local maximum. What follows?','Stationarity is insufficient','The loss must be minimized','The formula is impossible','The input must be zero','A maximum can be stationary; curvature or other analysis distinguishes it from a minimum.'],
['A model’s prediction derivative is large in one feature. Can that alone establish a causal effect?','No, it is model sensitivity','Yes, derivative means intervention','Yes, if units are normalized','Only if the value is positive','A fitted function’s sensitivity is not a causal identification argument about the data-generating process.'],
['A gradient checker gives inconsistent results as h shrinks. Which review is appropriate?','Precision and smoothness','Only file encoding','Only output font size','Only the dataset title','Finite differences depend on truncation, roundoff and differentiability assumptions.'],
['A team argues f′(x)=0 for one x proves a unique global optimum. What extra information is needed?','Global shape and feasible domain','Only one more decimal digit','Only a positive coordinate','Only a nonempty parameter name','Uniqueness/global optimality requires stronger conditions than stationarity at one point.']
]},
{id:'ma-gradient',comps:['m3.c2'],title:'Choose a learning rate by inspecting descent behavior',intro:'Gradient descent updates parameters opposite the slope of a loss. The learning rate controls step size: a good direction can still fail when the step is too large.',sections:[['Work through the update rule','For a scalar parameter w, gradient descent uses w_next=w−α f′(w), with positive learning rate α. For f(w)=(w−3)² the update is w_next=w−2α(w−3). Relative error e=w−3 therefore evolves as e_next=(1−2α)e.','This special quadratic converges from arbitrary finite starting error when |1−2α|<1, or 0<α<1. At α=1, the error flips sign without shrinking; above one, its magnitude grows. These boundaries depend on curvature and are not universal learning-rate recommendations.'],['Monitor objective and scale rather than one magic value','A small rate can yield slow progress; a large rate can oscillate or diverge. Feature scaling, curvature and optimizer choice affect useful step sizes. Stochastic mini-batch losses also fluctuate, so a single noisy step is not a complete convergence diagnosis.','Track training and validation behavior under a recorded schedule, iteration budget and tolerance. A small gradient can reflect a flat region rather than a good predictive solution. Numerical convergence does not by itself prove generalization, calibration or business suitability.']],problem:'Contrast stable, oscillating and divergent learning rates on one quadratic.',steps:['Start every trial at the same parameter.','Apply the same derivative with different step sizes.','Compare distance from the known target after four updates.'],code:'def run(alpha):\n    w=0.\n    for _ in range(4): w-=alpha*2*(w-3)\n    return round(w,6)\nprint([run(a) for a in [0.25,1.,1.1]])',expect:'[2.8125, 0.0, -3.2208]',limit:'These outcomes are exact properties of the stated quadratic and four updates. Real objectives have different curvature, stochastic noise and stopping considerations.',mistakes:['A learning rate stable for one loss is not guaranteed stable after rescaling another.','Decreasing training loss is not proof of held-out performance.'],takeaways:['Step size and curvature jointly determine update behavior.','Monitor progress with explicit budgets and validation.'],practice:[
['What is the descent update for derivative g and positive rate α?','w−αg','w+αg','w/g always','α−w','Subtracting the gradient gives a local descent direction for a sufficiently small appropriate step.'],
['For the lesson quadratic, what happens at α=1 from w=0?','Unshrinking oscillation','Immediate convergence always','A zero gradient forever','A monotone decrease to three','The error multiplier is -1, so the error alternates sign without shrinking.'],
['Can an extremely small rate cause slow learning?','Yes','No, every positive rate is equal','Only when outputs are strings','Only if weights are negative','The learning rate scales each update and can make parameter movement very small.'],
['A team rescales its loss by 100 and keeps the same rate. What changes?','Gradient step magnitude','Only the row count','Only coordinate labels','Nothing mathematical','Multiplying the loss multiplies its gradient, changing the effective update size.'],
['A training loss falls but validation loss rises. What should be reviewed?','Generalization','Only the update syntax','Only whether α is positive','Only output rounding','Optimization of training loss is distinct from generalization to held-out observations.'],
['A stochastic loss rises on one batch. What is a sensible conclusion?','Inspect the broader trajectory','Divergence is proved immediately','Convergence is proved immediately','All learning rates are invalid','Mini-batch noise can cause local fluctuations; assess trends and validation under the stated budget.'],
['A very large update crosses a minimum repeatedly. What adjustment is worth testing?','A smaller appropriate rate','A larger rate without checks','Deleting every derivative','Replacing labels with scores','Reducing step size can control overshoot, with validation of the actual objective and curvature.']
],formal:[
['Which hyperparameter scales a gradient-descent step?','Learning rate','Record identifier','Class name','Feature count alone','The rate multiplies the gradient to determine the update magnitude.'],
['For f(w)=(w−3)² and α=0.5, where does one update from zero go?','3','1.5','-3','6','The derivative is -6 at zero, so 0−0.5(-6)=3.'],
['Does minimizing training loss guarantee useful predictions on new data?','No','Yes by definition','Only for positive weights','Only for scalar losses','Generalization depends on data, model capacity, leakage and evaluation, not optimization alone.'],
['A service sees weights alternate with growing distance from a quadratic minimum. Which issue is plausible?','An excessive step size','Too many output labels','An always-zero gradient','An identity transformation','A step size too large relative to curvature can make the error multiplier’s magnitude exceed one.'],
['A training process barely moves over its budget. What is one possibility to investigate?','An overly small rate','Guaranteed perfect convergence','A necessarily negative loss','An automatically causal model','Small updates can make progress too slow; inspect gradients, scaling and implementation too.'],
['An engineer copies a learning rate from a differently scaled objective. What needs checking?','Gradient scale and curvature','Only the run name','Only the sample ordering label','Only decimal formatting','Appropriate rates depend on the magnitude and geometry of the actual objective.'],
['A model reaches low training loss but performs poorly on a new region. Which evidence is still needed?','Representative validation','Only more training iterations','Only a smaller printed error','Only confirmation of scalar output','Optimization success does not establish performance under distribution changes or new populations.'],
['A team stops because gradients are small. What limitation should be recorded?','Flatness is not universal quality','Small gradients prove causality','Small gradients imply no bias','Every stationary point is global','A small gradient can occur in flat or undesirable regions; objective and validation evidence remain necessary.'],
['A developer uses a negative learning rate in the usual subtraction rule. What happens to direction?','It reverses toward the gradient','It always preserves descent','It zeros every parameter','It normalizes every feature','Subtracting a negative multiple adds the gradient, reversing the intended local descent direction.'],
['A reviewer wants a universal rate valid for every differentiable function. What is the problem?','Curvature differs across objectives','All functions share one curvature','Rates depend only on filenames','Every loss is the same quadratic','Step-size guarantees need assumptions such as smoothness/curvature bounds; no unrestricted fixed rate serves every function.']
]},
{id:'ma-partials',comps:['m3.c1','m3.c2'],practice_comps:['m3.c1','m3.c1','m3.c1','m3.c1','m3.c1','m3.c2','m3.c2'],formal_comps:['m3.c1','m3.c1','m3.c1','m3.c2','m3.c1','m3.c1','m3.c2','m3.c1','m3.c2','m3.c1'],title:'Use gradients and chain rules in a two-parameter loss',intro:'Real models contain many parameters. A gradient collects partial derivatives so each parameter can be updated while accounting for its contribution to the same loss.',sections:[['Partial derivatives and the chain rule','For f(w1,w2), a partial derivative changes one coordinate while holding the others fixed. The gradient ∇f is the vector of these partials. For f=(w1−2)²+4(w2+1)², the gradient is (2(w1−2),8(w2+1)); the second direction has greater curvature.','The chain rule differentiates composed functions: if y=g(z) and z=h(w), then dy/dw=(dy/dz)(dz/dw) in the scalar case. Neural-network differentiation extends this principle through compatible Jacobians and sums over dependent paths. Automatic differentiation computes these rules on the implemented graph; it does not validate the graph’s business meaning.'],['Different curvature creates optimization tradeoffs','A single learning rate may move slowly in one direction and overshoot in another. Rescaling features, preconditioning or an appropriate optimizer can help, but each choice needs validation. Never infer stability solely from one coordinate’s improvement.','The example records a vector gradient and one simultaneous update. Simultaneous means both new coordinates use the old point; sequentially overwriting one coordinate inside a coupled gradient can implement a different algorithm. Finite-difference checks are useful on small smooth fixtures before scaling up.']],problem:'Compute a two-coordinate gradient and take one simultaneous update.',steps:['Evaluate both partials at the same old point.','Subtract the rate-scaled gradient coordinate by coordinate.','Evaluate loss before and after the step.'],code:'f=lambda w:(w[0]-2)**2+4*(w[1]+1)**2\nw=[0.,0.]\ng=[2*(w[0]-2),8*(w[1]+1)]\nnew=[a-0.1*b for a,b in zip(w,g)]\nprint(g)\nprint(new)\nprint(round(f(w),4), round(f(new),4))',expect:'[-4.0, 8.0]\n[0.4, -0.8]\n8.0 2.72',limit:'The lower loss verifies one step on this convex quadratic. It is not a convergence proof for every optimizer, learning rate or neural network.',mistakes:['Updating a coupled coordinate before computing every old-point partial changes the algorithm.','Automatic differentiation differentiates code, including the wrong code.'],takeaways:['A gradient is a vector in parameter space.','Validate derivatives, update semantics and held-out behavior separately.'],practice:[
['What does a gradient collect?','Partial derivatives','All sample identifiers','Only output labels','Only scalar intercepts','The gradient has one partial derivative for each differentiable parameter coordinate.'],
['A partial derivative holds what fixed?','The other coordinates','The target coordinate','Every output value','The derivative sign','It varies one coordinate while treating the other independent coordinates as constants.'],
['Which rule differentiates a composition?','Chain rule','Row sorting','Bayes rule','Median rule','The chain rule combines derivatives through dependent intermediate functions.'],
['A two-coordinate update uses one newly overwritten coordinate to calculate the other gradient. What needs checking?','The intended update algorithm','Only that both are numeric','Only output formatting','Only the parameter names','A simultaneous gradient step evaluates every partial at the same old parameter point.'],
['A library differentiates an incorrectly coded loss perfectly. What remains wrong?','The objective implementation','The chain rule itself','Every numeric gradient','The concept of a parameter','Automatic differentiation follows the implemented computation; it cannot repair a mistaken objective.'],
['One direction has much greater curvature. What challenge can this create?','An unbalanced rate','Every partial must be zero','Every update is identical','The model must be linear','A rate safe for one direction may overshoot another or be inefficient elsewhere.'],
['The loss falls after one test update. What is not proved?','General convergence','The observed loss values','The old-point gradient arithmetic','That an update occurred','One successful step does not establish convergence or generalization for an arbitrary process.']
],formal:[
['For f(x,y)=x²+y², what is the gradient?','(2x,2y)','(x+y,x+y)','(2,2) always','(xy,xy)','Each partial derivative differentiates its own squared term while holding the other coordinate fixed.'],
['In a simultaneous gradient step, where are partials evaluated?','At the same old point','At unrelated random points','Only after each overwrite','At the final unknown optimum','The update uses one gradient vector evaluated at the current parameter vector.'],
['What does automatic differentiation calculate?','Derivatives of implemented operations','Business correctness automatically','Future validation accuracy','Causal intervention effects','It applies differentiation rules to the program’s computation graph under supported operations.'],
['A retailer fits two coefficients with strongly unequal curvature. What issue might appear?','An ill-balanced step size','All gradients become identical','The output stops being scalar','The features become categorical','A common rate can be too aggressive along one direction and too slow along another.'],
['A neural layer is composed with a loss. What connects the derivatives?','The chain rule','Sorting the layer names','A shared row identifier','A fixed output probability','Derivatives propagate through intermediate variables via the chain rule and appropriate dimensions.'],
['A gradient vector has the wrong length for model parameters. What should training do?','Reject the mismatch','Silently truncate coordinates','Append random derivatives','Reuse the last derivative','Each parameter needs its corresponding partial derivative; a shape mismatch violates the update contract.'],
['A model’s code computes sum rather than mean loss after a batch-size change. What may change?','Gradient scale','Only label text','Only sample identifiers','Nothing mathematical','A summed loss scales with the batch contributions; mean and sum have different gradient magnitudes.'],
['A finite-difference test fails for one partial only. What is useful to isolate?','Its dependency path','Only the run directory','Only the output label order','Only the total row count','Coordinate-specific checks help locate missing paths, indexing mistakes or an incorrect analytic partial.'],
['A gradient method improves one loss component but raises the total. What must guide acceptance?','The declared full objective','Only the improved component','Only the longest parameter','Only a positive update count','The optimization contract concerns the combined objective and constraints, not a selected component alone.'],
['A report claims automatic gradients prove fair, reliable decisions. What extra evidence is needed?','Task and population validation','Only more derivative precision','Only a larger learning rate','Only a differentiable activation','Correct derivatives are one computational property, not proof of data quality, fairness, reliability or business suitability.']
]}
];
module.exports=course('math-for-ai',specs,['math']);
